def normalize_windows(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if os.name != 'nt':
        return cmd
    cmd_to_run = [cmd[0]]
    for arg in cmd[1:]:
        if arg[0] != '#':
            cmd_to_run.append(arg)
        elif arg == '#!':
            continue
        else:
            break
    return tuple(cmd_to_run)

